reply.body:
OK, I changed it to initialize everything to null in that case and catch the NullPointerException in `get()` to print a hopefully more helpful error message :)

```diff
diff --git a/substratevm/src/com.oracle.svm.graal/src/com/oracle/svm/graal/isolated/IsolatedSpeculationLog.java b/substratevm/src/com.oracle.svm.graal/src/com/oracle/svm/graal/isolated/IsolatedSpeculationLog.java
index 75a3eca830f..eb5a4f915b6 100644
--- a/substratevm/src/com.oracle.svm.graal/src/com/oracle/svm/graal/isolated/IsolatedSpeculationLog.java
+++ b/substratevm/src/com.oracle.svm.graal/src/com/oracle/svm/graal/isolated/IsolatedSpeculationLog.java
@@ -78,31 +78,34 @@ public final class IsolatedSpeculationLog extends IsolatedObjectProxy<Speculatio
         private static final String CLASS_NAME = "jdk.vm.ci.meta.SpeculationLog$SpeculationReasonEncoding";
 
         static {
-            Class<?> speculationReasonEncodingClass = null;
+            Class<?> speculationReasonEncodingClass;
             try {
                 speculationReasonEncodingClass = Class.forName(CLASS_NAME);
             } catch (ClassNotFoundException e) {
-                VMError.shouldNotReachHere(CLASS_NAME +
-                                " not found in JDK. UnencodedSpeculationReason should have been used as SpeculationReason");
+                speculationReasonEncodingClass = null;
             }
             CLASS = speculationReasonEncodingClass;
-            assert CLASS != null;
-            PROXY_CLASS = Proxy.newProxyInstance(CLASS.getClassLoader(), new Class<?>[]{CLASS},
-                            new SpeculationReasonInvocationHandler(new IsolatedSpeculationReasonEncoding())).getClass();
-            Constructor<?> declaredConstructor = null;
-            try {
-                declaredConstructor = PROXY_CLASS.getDeclaredConstructor(CLASS);
-            } catch (NoSuchMethodException e) {
-                VMError.shouldNotReachHere("Failed to get constructor for " + PROXY_CLASS);
+            if (CLASS != null) {
+                PROXY_CLASS = Proxy.newProxyInstance(CLASS.getClassLoader(), new Class<?>[]{CLASS},
+                        new SpeculationReasonInvocationHandler(new IsolatedSpeculationReasonEncoding())).getClass();
+                Constructor<?> declaredConstructor = null;
+                try {
+                    declaredConstructor = PROXY_CLASS.getDeclaredConstructor(CLASS);
+                } catch (NoSuchMethodException e) {
+                    VMError.shouldNotReachHere("Failed to get constructor for " + PROXY_CLASS);
+                }
+                CONSTRUCTOR = declaredConstructor;
+            } else {
+                PROXY_CLASS = null;
+                CONSTRUCTOR = null;
             }
-            CONSTRUCTOR = declaredConstructor;
         }
 
         @Override
         public Object get() {
             try {
                 return CONSTRUCTOR.newInstance(new SpeculationReasonInvocationHandler(new IsolatedSpeculationReasonEncoding()));
-            } catch (InstantiationException | IllegalAccessException | InvocationTargetException e) {
+            } catch (NullPointerException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
                 VMError.shouldNotReachHere("Failed to instantiate " + CLASS_NAME + "through proxy", e);
             }
             return null;
